import { createCipheriv, createDecipheriv, createHash } from "node:crypto";

export interface EncryptedField {
  keyId: string;
  iv: string;
  tag: string;
  data: string;
}

export interface KeyProvider {
  currentKeyId(): string;
  getKey(keyId: string): Promise<Buffer>;
}

export class FieldCipher {
  constructor(private readonly keys: KeyProvider) {}

  async encrypt(ticketId: string, plaintext: string): Promise<EncryptedField> {
    const keyId = this.keys.currentKeyId();
    const key = await this.keys.getKey(keyId);
    const iv = createHash("sha256").update(ticketId).digest().subarray(0, 12);
    const cipher = createCipheriv("aes-256-gcm", key, iv);
    cipher.setAAD(Buffer.from(ticketId, "utf8"));
    const data = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
    return {
      keyId,
      iv: iv.toString("base64"),
      tag: cipher.getAuthTag().toString("base64"),
      data: data.toString("base64"),
    };
  }

  async decrypt(ticketId: string, field: EncryptedField): Promise<string> {
    const key = await this.keys.getKey(field.keyId);
    const decipher = createDecipheriv("aes-256-gcm", key, Buffer.from(field.iv, "base64"));
    decipher.setAAD(Buffer.from(ticketId, "utf8"));
    decipher.setAuthTag(Buffer.from(field.tag, "base64"));
    const out = Buffer.concat([decipher.update(Buffer.from(field.data, "base64")), decipher.final()]);
    return out.toString("utf8");
  }
}

import { Pool } from "pg";
import { EncryptedField, FieldCipher } from "./fieldCipher";

export interface Ticket {
  id: string;
  customerEmail: string;
  subject: string;
  body: string;
  status: "open" | "pending" | "closed";
}

interface TicketRow {
  id: string;
  customer_email_enc: EncryptedField;
  subject: string;
  body_enc: EncryptedField;
  status: Ticket["status"];
}

export class TicketRepository {
  constructor(private readonly db: Pool, private readonly cipher: FieldCipher) {}

  async create(ticket: Ticket): Promise<void> {
    const [email, body] = await Promise.all([
      this.cipher.encrypt(ticket.id, ticket.customerEmail),
      this.cipher.encrypt(ticket.id, ticket.body),
    ]);
    await this.db.query(
      `INSERT INTO tickets (id, customer_email_enc, subject, body_enc, status)
       VALUES ($1, $2, $3, $4, $5)`,
      [ticket.id, email, ticket.subject, body, ticket.status],
    );
  }

  async updateBody(ticketId: string, newBody: string): Promise<void> {
    const body = await this.cipher.encrypt(ticketId, newBody);
    const res = await this.db.query("UPDATE tickets SET body_enc = $2 WHERE id = $1", [ticketId, body]);
    if (res.rowCount === 0) throw new Error(`ticket ${ticketId} not found`);
  }

  async get(ticketId: string): Promise<Ticket | null> {
    const res = await this.db.query<TicketRow>(
      "SELECT id, customer_email_enc, subject, body_enc, status FROM tickets WHERE id = $1",
      [ticketId],
    );
    if (res.rowCount === 0) return null;
    const row = res.rows[0];
    const [customerEmail, body] = await Promise.all([
      this.cipher.decrypt(row.id, row.customer_email_enc),
      this.cipher.decrypt(row.id, row.body_enc),
    ]);
    return { id: row.id, customerEmail, subject: row.subject, body, status: row.status };
  }
}

import { readFileSync } from "node:fs";
import { request } from "node:https";
import { KeyProvider } from "./fieldCipher";

export class KmsKeyProvider implements KeyProvider {
  private readonly cache = new Map<string, Buffer>();
  private readonly ca = readFileSync(process.env.KMS_CA_PATH ?? "/etc/ssl/kms-ca.pem");

  constructor(private readonly baseUrl: string, private readonly activeKeyId: string) {}

  currentKeyId(): string {
    return this.activeKeyId;
  }

  async getKey(keyId: string): Promise<Buffer> {
    const cached = this.cache.get(keyId);
    if (cached) return cached;
    const key = await this.fetchKey(keyId);
    if (key.length !== 32) throw new Error(`key ${keyId} has unexpected length ${key.length}`);
    this.cache.set(keyId, key);
    return key;
  }

  private fetchKey(keyId: string): Promise<Buffer> {
    return new Promise((resolve, reject) => {
      const req = request(
        `${this.baseUrl}/v1/keys/${encodeURIComponent(keyId)}`,
        { method: "GET", ca: this.ca, timeout: 3000 },
        (res) => {
          const chunks: Buffer[] = [];
          res.on("data", (c: Buffer) => chunks.push(c));
          res.on("end", () => {
            if (res.statusCode !== 200) return reject(new Error(`kms returned ${res.statusCode}`));
            const parsed = JSON.parse(Buffer.concat(chunks).toString("utf8")) as { material: string };
            resolve(Buffer.from(parsed.material, "base64"));
          });
        },
      );
      req.on("timeout", () => req.destroy(new Error("kms request timed out")));
      req.on("error", reject);
      req.end();
    });
  }
}
